function normalizePersonName(value) {
  return String(value || '').trim().toLocaleLowerCase('tr-TR').normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i').replace(/\s+/g, ' ');
}
function normalizePersonId(value) {
  if (value === null || value === undefined) return '';
  const raw = String(value).trim();
  const match = /^(?:(?:user|USER)_|Bitrix kullanıcı #)?([1-9]\d*)(?:\.0+)?$/.exec(raw);
  return match ? match[1] : '';
}
function resolvePerson(idValue, nameValue) {
  let id = normalizePersonId(idValue);
  const supplied = typeof nameValue === 'object' && nameValue !== null ? (nameValue.isim || nameValue.name || '') : nameValue;
  const name = ['string', 'number'].includes(typeof supplied) ? String(supplied).trim() : '';
  if (!id) id = normalizePersonId(name);
  if (id && Object.prototype.hasOwnProperty.call(PERSONELLER, id)) {
    return { id, ...PERSONELLER[id], listed: true, status: 'Personel listesi' };
  }
  if (!id && name) {
    const match = Object.entries(PERSONELLER).find(([,p]) => normalizePersonName(p.isim) === normalizePersonName(name));
    if (match) return { id: match[0], ...match[1], listed: true, status: 'Ad üzerinden personel listesi' };
  }
  const normalized = normalizePersonName(name);
  const invalidName = !name || /bilinm|sistem hata|baglan|atanmamis|kullanici #|personel listesinde|id eksik|object object|^[-?]+$/.test(normalized) || Boolean(normalizePersonId(name));
  return {
    id,
    isim: id ? (invalidName ? 'Personel listesinde yok (ID ' + id + ')' : name) : 'Sorumlu ID eksik',
    birim: 'Personel listesinde yok', listed: false,
    status: id ? 'Personel listesinde yok' : 'Sorumlu ID eksik'
  };
}

const CALL_RESULTS = {
  '200':'Başarılı','304':'Cevapsız','603':'Reddedildi','603-S':'İptal edildi',
  '404':'Geçersiz numara','486':'Meşgul','484':'Arama yönü kullanılamıyor','403':'Arama izni yok',
  '480':'Geçici olarak ulaşılamıyor','503':'Arama yönü kullanılamıyor','402':'Yetersiz bakiye','423':'Engellendi','OTHER':'Tanımlanmamış sonuç'
};
const CALL_DIRECTIONS = {'1':'Giden','2':'Gelen','3':'Yönlendirmeli gelen','4':'Geri arama','5':'Bilgilendirme araması'};
function callResult(code) { return CALL_RESULTS[String(code)] || (code ? 'Diğer sonuç (' + code + ')' : 'Sonuç kodu eksik'); }
function isCallRow(row) {
  const norm = v => String(v || '').trim().toLocaleUpperCase('tr-TR');
  return norm(row['Olay']) === 'ONVOXIMPLANTCALLEND' || norm(row['Olay Türü']) === 'ARAMA' ||
    norm(row['Kayıt Türü']) === 'ARAMA' || ['GERCEK_ARAMA','GERÇEK_ARAMA'].includes(norm(row.Kaynak));
}
function secondsValue(value) {
  const raw = String(value ?? '').trim();
  return /^\d+(?:\.\d+)?$/.test(raw) && Number.isFinite(Number(raw)) ? Number(raw) : null;
}
function legacyCallResult(value) {
  const label = String(value || '').trim().toLocaleUpperCase('tr-TR');
  const known = {'BAŞARILI':'200','BASARILI':'200','CEVAPSIZ':'304','REDDEDİLDİ':'603','REDDEDILDI':'603',
    'İPTAL EDİLDİ':'603-S','IPTAL EDILDI':'603-S','MEŞGUL':'486','MESGUL':'486'};
  return known[label] || '';
}

// weekly: replaced by the workflow builder; daily or weekly.
const period = 'weekly';
const zone = 'Europe/Istanbul';
const now = $now.setZone(zone);
let end;
if (period === 'daily') {
  end = now.startOf('day').set({ hour: 20 });
  if (end > now) end = end.minus({ days: 1 });
} else {
  end = now.startOf('day').minus({ days: (now.weekday - 6 + 7) % 7 }).set({ hour: 9 });
  if (end > now) end = end.minus({ days: 7 });
}
const start = end.minus({ days: period === 'daily' ? 1 : 7 });
const periodText = start.toFormat('dd.MM.yyyy HH:mm') + ' – ' + end.toFormat('dd.MM.yyyy HH:mm');
function parseDate(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' || /^\d{5}(?:\.\d+)?$/.test(String(value))) {
    const serial = Number(value);
    if (serial > 20000 && serial < 100000) return DateTime.fromObject({year:1899,month:12,day:30}, {zone:'UTC'}).plus({milliseconds:Math.round(serial * 86400000)}).setZone(zone, {keepLocalTime:true});
    return null;
  }
  const s = String(value).trim();
  for (const format of ['dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy HH:mm', 'dd.MM.yyyy', 'd.M.yyyy H:m:s', 'd.M.yyyy H:m', 'd.M.yyyy', 'yyyy-MM-dd HH:mm:ss']) {
    const dt = DateTime.fromFormat(s, format, {zone});
    if (dt.isValid) return dt;
  }
  const iso = DateTime.fromISO(s, {zone});
  return iso.isValid ? iso.setZone(zone) : null;
}
// --- Sheet satırları: başlık adına göre DEĞİL, yazılan sütun sırasına (A:AB) göre okunur. ---
// Webhook kolu values.append ile her satırı SHEET_COLUMNS sırasıyla yazar. Eski okuma başlık
// satırına güvendiği için başlıkta olmayan "Arama ID"/"CRM ID" sütunları boş geliyor, tüm
// aramalar "ID'siz eski satır" sayılıyor ve tekil CRM 0 çıkıyordu.
const SHEET_COLUMNS = ['Tarih','Müşteri Adı','Yeni Aşama','Kaynak','Sorumlu Kişi','Sorumlu ID','Birim','Görev',
  'Önceki Aşama','CRM ID','Kayıt Türü','CRM Başlığı','İşlemi Yapan ID','İşlemi Yapan','Aşama Bilgisi','Kayıt Zamanı',
  'Olay','Kontrol Notu','Olay Türü','Telefon','Arama ID','Arama Yönü','Arama Başlangıcı','Arama Süresi (sn)',
  'Arama Sonucu','Arama Sonuç Kodu','Arama Açıklaması','CRM Aktivite ID'];
const sheetResp = $('Sheet Oku (Haftalık, sütun sırasıyla)').first()?.json || {};
const sheetValues = Array.isArray(sheetResp.values) ? sheetResp.values : [];
const headerWarnings = [];
if (sheetResp.error) headerWarnings.push('Sheet okunamadı: ' + (sheetResp.error.message || JSON.stringify(sheetResp.error)).slice(0, 200));
let firstData = 0;
if (sheetValues.length && String(sheetValues[0][0] || '').trim() === 'Tarih') {
  firstData = 1;
  const header = sheetValues[0].map(v => String(v || '').trim());
  const diff = SHEET_COLUMNS.map((c, i) => header[i] === c ? null : ((i < 26 ? '' : 'A') + String.fromCharCode(65 + (i % 26)) + ':' + (header[i] || 'boş') + '≠' + c)).filter(Boolean);
  if (diff.length) headerWarnings.push('Sheet başlık satırı yazılan sütun sırasıyla uyuşmuyor (' + diff.slice(0, 8).join(', ') + (diff.length > 8 ? ' …' : '') + '). Veriler sütun sırasıyla okundu; başlık satırını düzeltmeniz önerilir.');
}
const rows = sheetValues.slice(firstData).map((vals, i) => {
  const o = { row_number: i + firstData + 1 };
  SHEET_COLUMNS.forEach((c, j) => { o[c] = vals[j] ?? ''; });
  return o;
}).filter(r => SHEET_COLUMNS.some(c => String(r[c]).trim() !== ''));

const invalid = [], selected = [];
for (const row of rows) {
  const dt = parseDate(row['Kayıt Zamanı']) || parseDate(row.Tarih);
  if (!dt) { invalid.push(row); continue; }
  if (dt >= start && dt < end) selected.push({ row, dt });
}
selected.sort((a,b) => a.dt.toMillis() - b.dt.toMillis());
const result = selected.map(({row}) => {
const call = isCallRow(row);
const owner = resolvePerson(row['Sorumlu ID'] || (call ? row.PORTAL_USER_ID : ''), row['Sorumlu Kişi']);
const editor = resolvePerson(row['İşlemi Yapan ID'], row['İşlemi Yapan']);
const durationRaw = call ? (row['Arama Süresi (sn)'] ?? row['Süre (sn)'] ?? row['Süre'] ?? row.CALL_DURATION) : '';
const duration = call ? secondsValue(durationRaw) : null;
const resultCode = call ? String(row['Arama Sonuç Kodu'] || row.CALL_FAILED_CODE || legacyCallResult(row['Arama Sonucu'] || row['Yeni Aşama'])) : '';
return {json:{
  'Satır Türü': call ? 'Arama' : 'Hareket',
  'Rapor Tarihi': end.toFormat('dd.MM.yyyy'),
  'Rapor Dönemi': periodText,
  'İşlem Zamanı': row.Tarih || row['Kayıt Zamanı'],
  'Kaynak': row.Kaynak || '-',
  'Müşteri Adı': row['Müşteri Adı'] || '-',
  'Önceki Aşama': row['Önceki Aşama'] || 'Bildirimde gönderilmedi',
  'Yeni Aşama': row['Yeni Aşama'] || '-',
  'Sorumlu Kişi': owner.isim,
  'Sorumlu ID': owner.id,
  'Birim': owner.birim,
  'Görev': owner.gorev || '',
  'Personel Eşleme': owner.status,
  'CRM ID': String(row['CRM ID'] || ''),
  'Kayıt Türü': call ? 'Arama' : row['Kayıt Türü'] || 'Lead',
  'İşlemi Yapan': editor.id ? editor.isim : '-',
  'Aşama Bilgisi': row['Aşama Bilgisi'] || '-',
  'Kayıt Zamanı': row['Kayıt Zamanı'] || '',
  'Kontrol Notu': row['Kontrol Notu'] || '',
  'Telefon': call ? (row['Telefon'] || row.PHONE_NUMBER || row['Müşteri Adı'] || '') : '',
  'Arama ID': call ? String(row['Arama ID'] || row.CALL_ID || '') : '',
  'Arama Yönü': call ? (row['Arama Yönü'] || CALL_DIRECTIONS[String(row.CALL_TYPE)] || 'Yön belirtilmedi') : '',
  'Arama Süresi (sn)': duration === null ? '' : duration,
  'Arama Sonucu': call ? (resultCode ? callResult(resultCode) : row['Arama Sonucu'] || row['Yeni Aşama'] || 'Sonuç kodu eksik') : '',
  'Arama Sonuç Kodu': resultCode,
  'Arama Açıklaması': call ? row['Arama Açıklaması'] || '' : '',
  'CRM Aktivite ID': call ? String(row['CRM Aktivite ID'] || row.CRM_ACTIVITY_ID || '') : '',
  'Bilgi': ''
}}; });
if (!result.length) result.push({json:{'Satır Türü':'Bilgi','Rapor Tarihi':end.toFormat('dd.MM.yyyy'),'Rapor Dönemi':periodText,'Bilgi':'Bu dönemde kayıt bulunamadı.'}});
// --- CRM hareketleri doğrudan Bitrix aşama geçmişinden (crm.stagehistory.list) alınır. ---
// Sheet'teki satırlar farklı sütun düzenleriyle yazıldığı için (Yeni Aşama sütununda GERCEK_ARAMA /
// kaynak kodları görünüyordu) sorumlu, CRM ID ve aşama güvenilir okunamıyordu.
function bxPages(nodeName) {
  let pages = [];
  try { pages = $(nodeName).all().map(i => i.json?.body && typeof i.json.body === 'object' ? i.json.body : i.json); }
  catch (e) { return { rows: [], error: 'düğüm çalışmadı' }; }
  const rows = []; let error = '';
  for (const p of pages) {
    if (p?.error) { error = String(p.error_description || p.error?.message || p.error); continue; }
    const r = p?.result;
    if (Array.isArray(r?.items)) rows.push(...r.items); else if (Array.isArray(r)) rows.push(...r);
  }
  return { rows, error: error || (pages.length ? '' : 'yanıt yok') };
}
const stageRes = bxPages('Bitrix Aşama Adları (Haftalık)'), leadHist = bxPages('Bitrix Lead Aşama Geçmişi (Haftalık)'), dealHist = bxPages('Bitrix Anlaşma Aşama Geçmişi (Haftalık)'), ownerRes = bxPages('Bitrix Kayıt Sorumluları (Haftalık)');
const crmApiOk = !leadHist.error && !dealHist.error;
if (crmApiOk) {
  const leadStage = {}, dealStage = {}, sourceName = {};
  for (const s of stageRes.rows) {
    const ent = String(s.ENTITY_ID || ''), id = String(s.STATUS_ID || ''), name = String(s.NAME || id);
    if (ent === 'STATUS') leadStage[id] = name;
    else if (ent.startsWith('DEAL_STAGE')) dealStage[id] = name;
    else if (ent === 'SOURCE') sourceName[id] = name;
  }
  const leads = {}, deals = {};
  for (const o of ownerRes.rows) { if ('STAGE_ID' in o) deals[String(o.ID)] = o; else leads[String(o.ID)] = o; }
  const sheetMoveCount = result.filter(r => r.json['Satır Türü'] === 'Hareket').length;
  for (let i = result.length - 1; i >= 0; i--) if (result[i].json['Satır Türü'] === 'Hareket') result.splice(i, 1);
  const hist = [
    ...leadHist.rows.map(h => ({ ...h, _type: 'LEAD', _stage: String(h.STATUS_ID || h.STAGE_ID || '') })),
    ...dealHist.rows.map(h => ({ ...h, _type: 'DEAL', _stage: String(h.STAGE_ID || h.STATUS_ID || '') }))
  ].map(h => ({ ...h, _dt: parseDate(h.CREATED_TIME) })).filter(h => h._dt && h._dt >= start && h._dt < end)
   .sort((a, b) => a._dt.toMillis() - b._dt.toMillis() || Number(a.ID) - Number(b.ID));
  const lastStage = {};
  let missingOwner = 0;
  for (const h of hist) {
    const oid = String(h.OWNER_ID || ''), key = h._type + ':' + oid;
    const rec = h._type === 'LEAD' ? leads[oid] : deals[oid];
    if (!rec) missingOwner++;
    const owner = resolvePerson(rec?.ASSIGNED_BY_ID, '');
    const names = h._type === 'LEAD' ? leadStage : dealStage;
    const stageName = names[h._stage] || h._stage || '-';
    const title = rec ? (String(rec.TITLE || '').trim() || [rec.NAME, rec.LAST_NAME].filter(Boolean).join(' ')) : '';
    const typeLabel = { '1': 'Kayıt oluşturuldu', '2': 'Aşama değişti', '3': 'Pipeline değişti' }[String(h.TYPE_ID)] || 'Aşama geçmişi';
    result.push({ json: {
      'Satır Türü': 'Hareket', 'Rapor Tarihi': end.toFormat('dd.MM.yyyy'), 'Rapor Dönemi': periodText,
      'İşlem Zamanı': h._dt.toFormat('dd.MM.yyyy HH:mm:ss'), 'Kaynak': rec ? (sourceName[rec.SOURCE_ID] || rec.SOURCE_ID || '-') : '-',
      'Müşteri Adı': title || (h._type === 'LEAD' ? 'Lead #' : 'Anlaşma #') + oid,
      'Önceki Aşama': lastStage[key] || '-', 'Yeni Aşama': stageName,
      'Sorumlu Kişi': owner.isim, 'Sorumlu ID': owner.id, 'Birim': owner.birim, 'Görev': owner.gorev || '', 'Personel Eşleme': owner.status,
      'CRM ID': oid, 'Kayıt Türü': h._type === 'LEAD' ? 'Lead' : 'Anlaşma', 'İşlemi Yapan': '-', 'Aşama Bilgisi': typeLabel,
      'Kayıt Zamanı': h._dt.toISO(), 'Kontrol Notu': rec ? (owner.listed ? '' : owner.status + (owner.id ? ': ' + owner.id : '')) : 'CRM kaydı okunamadı',
      'Telefon': '', 'Arama ID': '', 'Arama Yönü': '', 'Arama Süresi (sn)': '', 'Arama Sonucu': '', 'Arama Sonuç Kodu': '',
      'Arama Açıklaması': '', 'CRM Aktivite ID': '', 'Bilgi': ''
    } });
    lastStage[key] = stageName;
  }
  headerWarnings.push('CRM hareketleri Bitrix aşama geçmişinden alındı (' + hist.length + ' geçiş; Sheet\'teki ' + sheetMoveCount + ' satır kullanılmadı). Sorumlu, kaydın şu anki sorumlusudur.');
  if (missingOwner) headerWarnings.push(missingOwner + ' geçişin CRM kaydı okunamadı (silinmiş olabilir).');
  if (ownerRes.error) headerWarnings.push('Sorumlu bilgisi kısmen alınamadı: ' + ownerRes.error.slice(0, 160));
} else {
  headerWarnings.push('Bitrix aşama geçmişi alınamadı (' + (leadHist.error || dealHist.error).slice(0, 160) + '); CRM hareketleri Sheet satırlarından sayıldı ve güvenilir olmayabilir.');
}
// --- Aramalar doğrudan Bitrix telefoni istatistiğinden (voximplant.statistic.get) alınır. ---
// Webhook bildirimi kaçarsa veya eksik alanla gelirse Sheet'teki arama satırları eksik kalır;
// kaynak veri Bitrix'tir. API başarılıysa Sheet'teki arama satırları rapora alınmaz.
const apiCalls = [];
let apiError = '';
for (const item of $('Bitrix Aramaları (Haftalık)').all()) {
  const page = item.json?.body && typeof item.json.body === 'object' ? item.json.body : item.json;
  if (page?.error) { apiError = String(page.error_description || page.error?.message || page.error); continue; }
  if (Array.isArray(page?.result)) apiCalls.push(...page.result);
}
const apiOk = !apiError && $('Bitrix Aramaları (Haftalık)').all().length > 0;
if (apiOk) {
  const sheetCallCount = result.filter(r => r.json['Satır Türü'] === 'Arama').length;
