      'İşlem Zamanı':st.toFormat('dd.MM.yyyy HH:mm:ss'),'Kaynak':'BITRIX_TELEFONI','Müşteri Adı':c.PHONE_NUMBER || '-',
      'Önceki Aşama':'-','Yeni Aşama':callResult(code),'Sorumlu Kişi':owner.isim,'Sorumlu ID':owner.id,'Birim':owner.birim,
      'Görev':owner.gorev || '','Personel Eşleme':owner.status,'CRM ID':String(c.CRM_ENTITY_ID || ''),'Kayıt Türü':'Arama',
      'İşlemi Yapan':'-','Aşama Bilgisi':'Bitrix telefoni istatistiği','Kayıt Zamanı':st.toISO(),
      'Kontrol Notu':owner.listed ? '' : owner.status + (owner.id ? ': ' + owner.id : ''),
      'Telefon':c.PHONE_NUMBER || '','Arama ID':callId,'Arama Yönü':CALL_DIRECTIONS[String(c.CALL_TYPE)] || 'Tür ' + (c.CALL_TYPE || '?'),
      'Arama Süresi (sn)':duration === null ? '' : duration,'Arama Sonucu':callResult(code),'Arama Sonuç Kodu':code,
      'Arama Açıklaması':c.CALL_FAILED_REASON || '','CRM Aktivite ID':String(c.CRM_ACTIVITY_ID || ''),'Bilgi':''
    }});
