}
for (const w of headerWarnings) result.push({json:{'Satır Türü':'Uyarı','Rapor Tarihi':end.toFormat('dd.MM.yyyy'),'Rapor Dönemi':periodText,'Bilgi':w}});
if (invalid.length) result.push({json:{'Satır Türü':'Uyarı','Rapor Tarihi':end.toFormat('dd.MM.yyyy'),'Rapor Dönemi':periodText,'Bilgi':invalid.length + ' satırın tarihi okunamadı; dönem hesabına alınmadı. Sheet satırları: ' + invalid.slice(0,20).map(r => r.row_number || '?').join(', ')}});
// Yalnızca güncel personel listesindeki çalışanlar raporlanır.
const sadecePersonel = result.filter(r => !['Hareket', 'Arama'].includes(r.json['Satır Türü']) || ['Personel listesi', 'Ad üzerinden personel listesi'].includes(r.json['Personel Eşleme']));
if (!sadecePersonel.some(r => ['Hareket', 'Arama', 'Bilgi'].includes(r.json['Satır Türü']))) sadecePersonel.unshift({json:{'Satır Türü':'Bilgi','Rapor Tarihi':end.toFormat('dd.MM.yyyy'),'Rapor Dönemi':periodText,'Bilgi':'Bu dönemde kayıt bulunamadı.'}});
