  const name = ['string', 'number'].includes(typeof supplied) ? String(supplied).trim() : '';
  if (!id) id = normalizePersonId(name);
  if (id && Object.prototype.hasOwnProperty.call(PERSONELLER, id)) {
    return { id, ...PERSONELLER[id], listed: true, status: 'Personel listesi' };
  }
  if (!id && name) {
