if (period === 'daily') {
  end = now.startOf('day').set({ hour: 20 });
  if (end > now) end = end.minus({ days: 1 });
} else {
  end = now.startOf('day').minus({ days: (now.weekday - 6 + 7) % 7 }).set({ hour: 9 });
  if (end > now) end = end.minus({ days: 7 });
}
const start = end.minus({ days: period === 'daily' ? 1 : 7 });
const periodText = start.toFormat('dd.MM.yyyy HH:mm') + ' – ' + end.toFormat('dd.MM.yyyy HH:mm');
function parseDate(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' || /^\d{5}(?:\.\d+)?$/.test(String(value))) {
    const serial = Number(value);
    if (serial > 20000 && serial < 100000) return DateTime.fromObject({year:1899,month:12,day:30}, {zone:'UTC'}).plus({milliseconds:Math.round(serial * 86400000)}).setZone(zone, {keepLocalTime:true});
    return null;
  }
  const s = String(value).trim();
  for (const format of ['dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy HH:mm', 'dd.MM.yyyy', 'd.M.yyyy H:m:s', 'd.M.yyyy H:m', 'd.M.yyyy', 'yyyy-MM-dd HH:mm:ss']) {
    const dt = DateTime.fromFormat(s, format, {zone});
