  if (!dt) { invalid.push(row); continue; }
  if (dt >= start && dt < end) selected.push({ row, dt });
}
selected.sort((a,b) => a.dt.toMillis() - b.dt.toMillis());
const result = selected.map(({row}) => {
const call = isCallRow(row);
const owner = resolvePerson(row['Sorumlu ID'] || (call ? row.PORTAL_USER_ID : ''), row['Sorumlu Kişi']);
const editor = resolvePerson(row['İşlemi Yapan ID'], row['İşlemi Yapan']);
const durationRaw = call ? (row['Arama Süresi (sn)'] ?? row['Süre (sn)'] ?? row['Süre'] ?? row.CALL_DURATION) : '';
const duration = call ? secondsValue(durationRaw) : null;
const resultCode = call ? String(row['Arama Sonuç Kodu'] || row.CALL_FAILED_CODE || legacyCallResult(row['Arama Sonucu'] || row['Yeni Aşama'])) : '';
