function normalizePersonName(value) {
  return String(value || '').trim().toLocaleLowerCase('tr-TR').normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i').replace(/\s+/g, ' ');
}
function normalizePersonId(value) {
  if (value === null || value === undefined) return '';
  const raw = String(value).trim();
  const match = /^(?:(?:user|USER)_|Bitrix kullanıcı #)?([1-9]\d*)(?:\.0+)?$/.exec(raw);
  return match ? match[1] : '';
}
function resolvePerson(idValue, nameValue) {
  let id = normalizePersonId(idValue);
  const supplied = typeof nameValue === 'object' && nameValue !== null ? (nameValue.isim || nameValue.name || '') : nameValue;
  const name = ['string', 'number'].includes(typeof supplied) ? String(supplied).trim() : '';
  if (!id) id = normalizePersonId(name);
  if (id && Object.prototype.hasOwnProperty.call(PERSONELLER, id)) {
    return { id, ...PERSONELLER[id], listed: true, status: 'Personel listesi' };
  }
  if (!id && name) {
    const match = Object.entries(PERSONELLER).find(([,p]) => normalizePersonName(p.isim) === normalizePersonName(name));
    if (match) return { id: match[0], ...match[1], listed: true, status: 'Ad üzerinden personel listesi' };
  }
  const normalized = normalizePersonName(name);
  const invalidName = !name || /bilinm|sistem hata|baglan|atanmamis|kullanici #|personel listesinde|id eksik|object object|^[-?]+$/.test(normalized) || Boolean(normalizePersonId(name));
  return {
    id,
    isim: id ? (invalidName ? 'Personel listesinde yok (ID ' + id + ')' : name) : 'Sorumlu ID eksik',
    birim: 'Personel listesinde yok', listed: false,
    status: id ? 'Personel listesinde yok' : 'Sorumlu ID eksik'
  };
}

