// Rapor dönemi: Filtrele düğümüyle aynı hesap. Bitrix telefoni sorgusunun gövdesini üretir.
const period = 'daily';
const zone = 'Europe/Istanbul';
const now = $now.setZone(zone);
let end;
if (period === 'daily') {
  end = now.startOf('day').set({ hour: 20 });
  if (end > now) end = end.minus({ days: 1 });
} else {
  end = now.startOf('day').minus({ days: (now.weekday - 6 + 7) % 7 }).set({ hour: 9 });
  if (end > now) end = end.minus({ days: 7 });
}
const start = end.minus({ days: period === 'daily' ? 1 : 7 });
const f = d => d.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");
return [{ json: { period, start: f(start), end: f(end), callBody: { FILTER: { '>=CALL_START_DATE': f(start), '<CALL_START_DATE': f(end) }, SORT: 'ID', ORDER: 'ASC', start: 0 } } }];

// Aşama geçmişindeki lead/anlaşma ID'lerini 50'lik gruplara böler; her grup bir Bitrix isteğidir.
// Sorumlu (ASSIGNED_BY_ID), müşteri adı ve kaynak buradan alınır.
function items(nodeName) {
  const out = [];
  for (const i of $(nodeName).all()) {
    const r = i.json?.body && typeof i.json.body === 'object' ? i.json.body : i.json;
    const res = r?.result;
    if (Array.isArray(res?.items)) out.push(...res.items); else if (Array.isArray(res)) out.push(...res);
  }
  return out;
}
const leadIds = [...new Set(items('Bitrix Lead Aşama Geçmişi (Günlük)').map(h => String(h.OWNER_ID || '')).filter(Boolean))];
const dealIds = [...new Set(items('Bitrix Anlaşma Aşama Geçmişi (Günlük)').map(h => String(h.OWNER_ID || '')).filter(Boolean))];
const out = [];
for (let i = 0; i < leadIds.length; i += 50) out.push({ json: { method: 'crm.lead.list', body: { filter: { '@ID': leadIds.slice(i, i + 50) }, select: ['ID','TITLE','NAME','LAST_NAME','ASSIGNED_BY_ID','SOURCE_ID','STATUS_ID'], start: 0 } } });
for (let i = 0; i < dealIds.length; i += 50) out.push({ json: { method: 'crm.deal.list', body: { filter: { '@ID': dealIds.slice(i, i + 50) }, select: ['ID','TITLE','ASSIGNED_BY_ID','SOURCE_ID','STAGE_ID'], start: 0 } } });
// Hiç geçmiş yoksa zincir kopmasın diye boş sonuç dönen tek istek.
if (!out.length) out.push({ json: { method: 'crm.lead.list', body: { filter: { ID: 0 }, select: ['ID'], start: 0 } } });
return out;

