// Gün sonu özet metnini Telegram'ın 4096 karakter sınırına göre parçalar.
const text = String($('Gün Sonu Özetini Hazırla').first().json.summaryText || '');
const max = 3500, chunks = [];
let rest = text;
while (rest.length > max) {
  let cut = rest.lastIndexOf('\n', max);
  if (cut < 1000) cut = max;
  chunks.push(rest.slice(0, cut));
  rest = rest.slice(cut).replace(/^\n+/, '');
}
if (rest) chunks.push(rest);
return chunks.map((t, i) => ({ json: { text: chunks.length > 1 ? `(${i + 1}/${chunks.length})\n` + t : t } }));

